import 'package:yakku/core/constants/api_constants.dart';
import 'package:yakku/core/router/app_routes.dart';

/// Parses the canonical shared-poll link `https://<web host>/vote/{shareCode}`.
///
/// The link carries the poll's share code, never its id. The OS only hands
/// the app links for the verified host and `/vote/` prefix (see
/// AndroidManifest.xml / Associated Domains); this is the second, in-app line
/// of validation. Query strings and fragments are never trusted.
abstract final class PollDeepLink {
  /// Share codes are generated by the backend: letters and digits only.
  /// They are case-sensitive, so they are never lower-cased.
  static final RegExp _shareCode = RegExp(r'^[A-Za-z0-9]{6,64}$');

  /// Query parameter carrying the post-onboarding destination.
  static const returnToParam = 'from';

  static bool isValidShareCode(String? value) =>
      value != null && _shareCode.hasMatch(value);

  /// Returns the share code for a full shared-poll URL, or `null` for any
  /// other host, scheme, path shape or malformed code.
  static String? shareCodeFromUrl(
    Uri uri, {
    String webBaseUrl = ApiConstants.webBaseUrl,
  }) {
    final base = Uri.tryParse(webBaseUrl);
    if (base == null) return null;
    if (uri.scheme.toLowerCase() != 'https') return null;
    if (uri.host.toLowerCase() != base.host.toLowerCase()) return null;
    return _shareCodeFromSegments(uri.pathSegments);
  }

  /// Same as [shareCodeFromUrl] for an in-app location such as
  /// `/vote/{shareCode}` (go_router drops scheme and host for incoming links).
  static String? shareCodeFromPath(Uri location) =>
      _shareCodeFromSegments(location.pathSegments);

  static String? _shareCodeFromSegments(List<String> segments) {
    final parts = segments.where((s) => s.isNotEmpty).toList(growable: false);
    if (parts.length != 2 || parts.first != 'vote') return null;
    final code = parts[1];
    return isValidShareCode(code) ? code : null;
  }

  /// A return-to value is only honoured when it is an in-app shared-poll path.
  static String? safeReturnPath(String? raw) {
    if (raw == null || raw.isEmpty) return null;
    final uri = Uri.tryParse(raw);
    if (uri == null || uri.hasScheme || uri.hasAuthority) return null;
    final code = shareCodeFromPath(uri);
    return code == null ? null : AppRoutes.pollVoteLocation(code);
  }
}
